      filter.type = "lowpass";
      filter.Q.value = 1.8;
      filter.frequency.setValueAtTime(profile.bassCutoffStart ?? 680, time);
      filter.frequency.exponentialRampToValueAtTime(profile.bassCutoffEnd ?? 145, time + Math.min(0.2, durSec * 0.8));
      const amp = ctx.createGain();
      const peak = (profile.bassGain ?? 0.31) * vel;
      const endTime = time + Math.max(0.08, durSec);
      amp.gain.setValueAtTime(1e-4, time);
      amp.gain.linearRampToValueAtTime(peak, time + 9e-3);
      amp.gain.exponentialRampToValueAtTime(Math.max(1e-4, peak * 0.55), endTime - 0.025);
      amp.gain.exponentialRampToValueAtTime(1e-4, endTime + 0.03);
      filter.connect(amp);
      amp.connect(target);
      const tri = ctx.createOscillator();
      tri.type = "triangle";
      tri.frequency.setValueAtTime(freq, time);
      tri.connect(filter);
      tri.start(time);
      tri.stop(endTime + 0.04);
