      saw.type = "sawtooth";
      saw.frequency.setValueAtTime(freq, time);
      const sawGain = ctx.createGain();
      sawGain.gain.setValueAtTime(0.45, time);
      saw.connect(sawGain);
      sawGain.connect(filter);
      saw.start(time);
      saw.stop(endTime + 0.04);
