      sub.type = "sine";
      sub.frequency.setValueAtTime(freq, time);
      const subGain = ctx.createGain();
      subGain.gain.setValueAtTime(0.68, time);
      sub.connect(subGain);
      subGain.connect(amp);
      sub.start(time);
      sub.stop(endTime + 0.04);
