      amp.gain.setValueAtTime(1e-4, time);
      amp.gain.linearRampToValueAtTime(peak, time + (isBright || isArcade ? 8e-3 : 0.024));
      amp.gain.exponentialRampToValueAtTime(Math.max(1e-4, peak * (isBright ? 0.8 : 0.74)), Math.max(time + 0.03, noteEnd - 0.02));
      amp.gain.exponentialRampToValueAtTime(1e-4, releaseEnd);
      filter.connect(amp);
      amp.connect(target);
